-- Part 6 (diversification pass): MCQ top-up for survey_inspector and goods_materials_inspector.
-- These are the two newest job roles (added this session) and were explicitly named as the
-- thinnest MCQ pools (36 and 35 questions respectively) alongside the 30-floor roles. Adds ~18
-- questions per role on topics not already covered by mcq_new_roles_seed.sql (verified by
-- listing that file's topics): closure-error calculation, GNSS baseline QA, benchmark network
-- hierarchy, settlement monitoring, AQL sampling plans, heat-number traceability, preservation
-- of stored machinery, bolt/gasket incoming inspection. Domain grounding: FGDC/ASPRS surveying
-- accuracy standards, ASTM E122/ANSI Z1.4 (AQL sampling), ASTM A6/mill test certificates, API
-- storage & preservation practice.

insert into comp_mcq_questions (job_role, category, topic, difficulty, stem_fa, options, correct_option, explanation_fa, standard_ref, approval_status, active)
select 'survey_inspector', x ->> 0, x ->> 1, (x ->> 2)::smallint, x ->> 3,
  (select jsonb_agg(x -> 4 -> ((i - r.k + 4) % 4) order by i) from generate_series(0, 3) i),
  ((n - 1) % 4)::smallint, x ->> 6, x ->> 7, 'APPROVED', true
from jsonb_array_elements($mcq$[
["TECHNICAL", "محاسبه خطای بست ترازیابی", 3, "در یک حلقه ترازیابی بسته، مجموع اختلاف ارتفاع رفت و برگشت ۸ میلی‌متر است. اگر تلورانس مجاز پروژه ۱۲ میلی‌متر بر جذر کیلومتر (۱۲√K) و طول مسیر ۴ کیلومتر باشد، آیا خطای بست قابل قبول است؟", ["خیر، چون ۸ همیشه از ۱۲ بزرگ‌تر است", "بله، چون تلورانس مجاز ۱۲×۲=۲۴ میلی‌متر است و ۸ کمتر از آن است", "تلورانس ارتباطی به طول مسیر ندارد", "بدون دستگاه نمی‌توان قضاوت کرد"], 1, "تلورانس = 12×√4 = 12×2 = 24 میلی‌متر؛ خطای بست ۸ میلی‌متر به‌وضوح کمتر و قابل قبول است.", "استاندارد دقت ترازیابی (Leveling Closure Tolerance)"],
["TECHNICAL", "پردازش خط مبنای GNSS", 2, "چرا پردازش خط مبنای GNSS (Baseline Processing) با نرم‌افزار تخصصی به داده خام دو گیرنده نیاز دارد، نه فقط مختصات نهایی هر گیرنده؟", ["فقط برای پیچیده‌تر کردن کار", "محاسبه دقیق بردار نسبی بین دو گیرنده و رفع خطاهای مشترک (مثل خطای ساعت ماهواره) نیازمند داده خام هر دو ایستگاه هم‌زمان است", "مختصات نهایی هر گیرنده به‌تنهایی همیشه کافی است", "پردازش خط مبنا فقط برای نقشه‌برداری هوایی کاربرد دارد"], 1, "روش تفاضلی (Differential) با استفاده از داده خام هم‌زمان دو گیرنده، خطاهای مشترک اتمسفری و ساعت ماهواره را حذف و دقت را به‌شدت افزایش می‌دهد.", "اصول پردازش خط مبنای GNSS (Differential GPS)"],
["TECHNICAL", "سلسله‌مراتب شبکه بنچمارک", 2, "چرا شبکه نقاط کنترل (بنچمارک) یک پروژه بزرگ باید سلسله‌مراتبی (کنترل اصلی، ثانویه، اجرایی) طراحی شود؟", ["فقط برای زیبایی مستندات", "کنترل خطای انباشته با ایجاد نقاط ثانویه/اجرایی از نقاط اصلی با دقت بالاتر، به‌جای زنجیره طولانی بدون بازبینی", "سلسله‌مراتب هیچ تاثیری بر دقت ندارد", "فقط برای تسهیل تقسیم مسئولیت بین تیم‌ها است"], 1, "طراحی سلسله‌مراتبی خطای انباشته در زنجیره‌های طولانی نقشه‌برداری را کنترل و امکان بازبینی دوره‌ای دقت را فراهم می‌کند.", "اصول طراحی شبکه کنترل نقشه‌برداری (Control Network Hierarchy)"],
["TECHNICAL", "پایش نشست سازه‌ای", 3, "پایش نشست (Settlement Monitoring) دوره‌ای یک مخزن بزرگ پس از پر شدن اولیه چه هدف فنی دارد؟", ["فقط ثبت آماری بدون کاربرد مهندسی", "تشخیص زودهنگام نشست نامتقارن یا بیش از حد مجاز که می‌تواند به آسیب سازه‌ای یا نشتی منجر شود", "اندازه‌گیری حجم مایع داخل مخزن", "تعیین رنگ نهایی مخزن"], 1, "نشست نامتقارن یا بیش از حد مجاز می‌تواند تنش‌های مضر در پوسته/فونداسیون مخزن ایجاد کند؛ پایش دوره‌ای امکان مداخله زودهنگام می‌دهد.", "رویه پایش نشست سازه‌ای (Settlement Monitoring) / API 653"],
["TECHNICAL", "کدام گزینه نادرست دقت GPS-RTK", 2, "کدام گزینه درباره محدودیت‌های دقت GPS-RTK نادرست است؟", ["نزدیکی به موانع بزرگ (ساختمان، درخت انبوه) می‌تواند دقت را کاهش دهد", "شرایط اتمسفری و تعداد ماهواره‌های قابل‌مشاهده بر دقت اثر دارند", "دقت RTK همیشه مستقل از فاصله از ایستگاه مرجع (Base) است", "برای کارهای دقیق سازه‌ای، بررسی وضعیت PDOP پیش از برداشت توصیه می‌شود"], 2, "دقت RTK با افزایش فاصله از ایستگاه مرجع معمولاً کاهش می‌یابد (به‌ویژه بدون شبکه تصحیح دائمی)؛ این گزینه نادرست است.", "اصول دقت GPS-RTK"],
["GENERAL", "مستندسازی گزارش برداشت میدانی", 2, "چرا ثبت شرایط محیطی (آب‌وهوا، وضعیت دستگاه، شماره کالیبراسیون) در گزارش برداشت میدانی نقشه‌برداری مهم است؟", ["فقط الزام اداری بدون کاربرد", "در صورت بروز شک بعدی درباره صحت داده، این اطلاعات زمینه‌ای برای ارزیابی قابلیت اعتماد داده فراهم می‌کند", "شرایط محیطی هیچ تاثیری بر دقت برداشت ندارد", "فقط برای آرشیو تاریخی است"], 1, "در صورت مغایرت بعدی، دانستن شرایط زمان برداشت (وضعیت جوی، کالیبراسیون) کمک می‌کند تا علت احتمالی خطا شناسایی شود.", "رویه مستندسازی برداشت میدانی نقشه‌برداری"],
["HSE", "ایمنی کار در نزدیکی راه‌آهن/جاده فعال", 2, "برای برداشت نقشه‌برداری در حاشیه یک جاده یا راه‌آهن فعال، کدام کنترل ایمنی الزامی است؟", ["کار بدون هیچ علامت‌گذاری چون کار کوتاه‌مدت است", "استفاده از تجهیزات هشداردهنده (مخروط، تابلو) و لباس پرتاب‌نور، و هماهنگی با مرجع کنترل ترافیک در صورت نیاز", "ایستادن در حاشیه جاده بدون هیچ حفاظت اضافی", "کار فقط در شب برای کاهش تردد"], 1, "کار در حاشیه مسیرهای فعال بدون علامت‌گذاری و لباس مشخص ریسک برخورد با وسایل نقلیه را افزایش می‌دهد.", "دستورالعمل ایمنی کار نزدیک ترافیک فعال (Traffic Control Safety)"],
["SCENARIO", "کشف اختلاف بزرگ بین دو دستگاه توتال استیشن", 2, "دو دستگاه توتال استیشن برای یک نقطه کنترل یکسان، مختصات با اختلاف بیش از تلورانس نشان می‌دهند. اقدام درست چیست؟", ["میانگین‌گیری ساده بین دو عدد", "بررسی کالیبراسیون هر دو دستگاه و تکرار اندازه‌گیری از یک نقطه مرجع شناخته‌شده برای تشخیص دستگاه معیوب", "استفاده از دستگاه گران‌تر بدون بررسی بیشتر", "نادیده گرفتن اختلاف تا پایان پروژه"], 1, "اختلاف بیش از تلورانس باید با بررسی کالیبراسیون و تکرار اندازه‌گیری از نقطه مرجع شناخته‌شده ریشه‌یابی شود، نه میانگین‌گیری کورکورانه.", "رویه راستی‌آزمایی اختلاف دستگاه‌های نقشه‌برداری"],
["JUDGMENT", "قضاوت درباره پذیرش انحراف جزئی چون‌ساخت خط لوله", 3, "انحراف موقعیت چون‌ساخت یک بخش کوتاه از خط لوله نسبت به طراحی اندکی بیش از تلورانس مجاز است اما در محدوده حریم مجاز باقی می‌ماند. تصمیم درست چیست؟", ["پذیرش خودکار چون در محدوده حریم است", "گزارش دقیق انحراف به مهندس طراح برای ارزیابی تاثیر واقعی (مثل تداخل احتمالی با تاسیسات دیگر) پیش از پذیرش نهایی", "رد خودکار و الزام اصلاح فیزیکی بدون بررسی تاثیر واقعی", "نادیده گرفتن انحراف چون جزئی است"], 1, "ماندن در محدوده حریم به‌تنهایی کافی نیست؛ باید تاثیر واقعی انحراف (مثل فاصله از تاسیسات مجاور) توسط طراح ارزیابی شود.", "رویه ارزیابی انحراف As-Built از طراحی"],
["PROBLEM_SOLVING", "تکرار خطای مشابه در چند برداشت مقطع عرضی", 2, "خطای مشابه (جابجایی ارتفاعی سیستماتیک) در چند برداشت مقطع عرضی مختلف توسط یک اپراتور مشاهده می‌شود. اولین گام تحلیلی درست چیست؟", ["تکرار برداشت بدون بررسی علت", "بررسی تنظیمات دستگاه (ارتفاع آنتن، پارامتر ژئوئید) و روش کار آن اپراتور برای یافتن خطای سیستماتیک مشترک", "نادیده گرفتن چون خطا کوچک است", "تعویض اپراتور بدون بررسی علت فنی"], 1, "خطای سیستماتیک تکراری معمولاً از یک تنظیم اشتباه ثابت (نه خطای تصادفی) ناشی می‌شود که باید در پیکربندی/روش کار یافت شود.", "رویه تشخیص خطای سیستماتیک نقشه‌برداری"]
]$mcq$::jsonb) with ordinality t(x, n)
cross join lateral (select ((((n - 1) % 4)::int - (x ->> 5)::int + 4) % 4) as k) r
on conflict (job_role, md5(stem_fa)) do nothing;

insert into comp_mcq_questions (job_role, category, topic, difficulty, stem_fa, options, correct_option, explanation_fa, standard_ref, approval_status, active)
select 'goods_materials_inspector', x ->> 0, x ->> 1, (x ->> 2)::smallint, x ->> 3,
  (select jsonb_agg(x -> 4 -> ((i - r.k + 4) % 4) order by i) from generate_series(0, 3) i),
  ((n - 1) % 4)::smallint, x ->> 6, x ->> 7, 'APPROVED', true
from jsonb_array_elements($mcq$[
["TECHNICAL", "ردیابی شماره ذوب (Heat Number)", 2, "چرا ردیابی شماره ذوب (Heat Number) فولاد از تولید تا نصب نهایی در پروژه‌های صنعتی اهمیت دارد؟", ["فقط برای زیبایی مستندات", "امکان ردیابی دقیق ترکیب شیمیایی/خواص مکانیکی واقعی هر قطعه تا منبع تولید آن، به‌ویژه در صورت کشف مشکل کیفی بعدی", "شماره ذوب فقط برای محاسبه قیمت کاربرد دارد", "شماره ذوب فقط برای فولادهای وارداتی الزامی است"], 1, "در صورت کشف مشکل کیفی، ردیابی شماره ذوب امکان شناسایی سریع همه قطعات از همان دسته تولید و محدودسازی دامنه اقدام اصلاحی را می‌دهد.", "ASTM A6 / رویه ردیابی مواد (Material Traceability)"],
["TECHNICAL", "طرح نمونه‌برداری AQL", 2, "طرح نمونه‌برداری بر مبنای سطح کیفیت قابل‌قبول (Acceptable Quality Level, AQL) عمدتاً چه چیزی را تعیین می‌کند؟", ["بازرسی صد‌درصد اجباری همه اقلام", "تعداد نمونه بازرسی و تعداد حداکثر مجاز اقلام معیوب در آن نمونه برای پذیرش کل محموله", "فقط قیمت نهایی محموله", "رنگ برچسب‌گذاری محموله"], 1, "AQL/ANSI Z1.4 اندازه نمونه و معیار پذیرش/رد را بر مبنای اندازه کل محموله و سطح کیفیت قابل‌قبول تعیین می‌کند.", "ANSI/ASQ Z1.4 (Sampling Procedures)"],
["TECHNICAL", "کدام گزینه نادرست نگهداری تجهیز دوار در انبار", 2, "کدام گزینه درباره نگهداری صحیح یک تجهیز دوار (مثل پمپ) در انبار طولانی‌مدت نادرست است؟", ["چرخاندن دوره‌ای شافت برای جلوگیری از تغییر شکل دائمی بیرینگ توصیه می‌شود", "روغن‌کاری/محافظت ضدزنگ سطوح ماشین‌کاری‌شده باید طبق دستورالعمل سازنده حفظ شود", "تجهیز دوار می‌تواند بدون هیچ نگهداری ویژه برای سال‌ها در انبار باز رها شود", "کنترل رطوبت محیط انبار برای جلوگیری از خوردگی داخلی اهمیت دارد"], 2, "رهاسازی بدون نگهداری ویژه (چرخاندن دوره‌ای، کنترل رطوبت، محافظت ضدزنگ) می‌تواند به آسیب بیرینگ و خوردگی داخلی منجر شود؛ این گزینه نادرست است.", "رویه نگهداری تجهیزات دوار در انبار (Preservation of Rotating Equipment)"],
["TECHNICAL", "محاسبه ساده تعداد نمونه بازرسی", 3, "طبق جدول نمونه‌برداری پروژه، برای محموله‌ای با ۵۰۰ قلم، حرف کد اندازه نمونه «H» تعیین شده که معادل نمونه ۵۰ تایی است. اگر حداکثر ۲ قلم معیوب در نمونه مجاز باشد و ۳ قلم معیوب در نمونه ۵۰ تایی یافت شود، نتیجه چیست؟", ["پذیرش کامل محموله چون تعداد کل معیوب کم است", "رد محموله طبق معیار پذیرش/رد طرح نمونه‌برداری، چون تعداد معیوب از حد مجاز فراتر رفته", "تکرار نمونه‌برداری با نمونه بزرگ‌تر بدون رد رسمی", "نادیده گرفتن معیوب‌ها چون کمتر از ۵٪ نمونه هستند"], 1, "طبق طرح نمونه‌برداری، اگر تعداد معیوب یافت‌شده (۳) از حداکثر مجاز (۲) بیشتر باشد، کل محموله باید طبق رویه رد شود، صرف‌نظر از درصد.", "ANSI/ASQ Z1.4 (معیار پذیرش/رد نمونه)"],
["GENERAL", "مدیریت تاریخ انقضای اقلام مصرفی انبارشده", 2, "چرا پایش منظم تاریخ انقضای اقلام مصرفی حساس (مثل الکترود جوش هیدروژن پایین یا رزین‌های اپوکسی) در انبار پروژه اهمیت دارد؟", ["فقط الزام اداری بدون کاربرد فنی", "مصرف اقلام منقضی‌شده می‌تواند کیفیت نهایی جوش/پوشش را به‌طور جدی کاهش دهد بدون آن‌که ظاهراً قابل تشخیص باشد", "تاریخ انقضا فقط برای مواد غذایی معنا دارد", "اقلام مصرفی صنعتی هرگز منقضی نمی‌شوند"], 1, "بسیاری مواد مصرفی صنعتی (الکترود، رزین) پس از انقضا خواص فنی لازم را از دست می‌دهند، حتی اگر ظاهر آن‌ها سالم به نظر برسد.", "رویه مدیریت انبارش و تاریخ انقضای مواد مصرفی"],
